/**
 * Test-only reader and formula evaluator for the workbooks generated by the tool. Supports the subset of
 * Excel used by the export: COUNTIFS, SUMIFS, COUNTIF (also with an array of criteria, inside SUMPRODUCT), SUMIF,
 * COUNTA, ROWS, WEEKDAY, EXACT, SUM, SUMPRODUCT, ROUND, IF, IFERROR, ISNUMBER, INDEX, MATCH (exact), AND, OR, NOT, LEN,
 * TRIM, ABS, MAX, MIN, DATE, DAY, MONTH, YEAR, FIXED, LEFT, RIGHT, MID, LOWER, arithmetic, comparison and "&", ranges
 * with sheet names and defined names. Criteria strings follow Excel (">=46266", "<>Não identificado", "", "Manual").
 *
 * Number to text: Excel formats with the separators of the language of the user, not of the workbook. The evaluator
 * assumes Excel in pt-BR (`locale = 'pt-BR'`, the default: FIXED(1234.5,2) = "1.234,50", 1.5&"" = "1,5") for the
 * Portuguese workpaper and Excel in en-US (`locale = 'en-US'`: "1,234.50", "1.5") for the English one, so a text
 * formula can be compared with the text of the engine (src/shared/format.ts, pt-BR).
 */
import { strFromU8, unzipSync } from 'fflate';

export type Value = number | string | boolean | null | Value[] | { error: string };
interface CellData {
  v: number | string | boolean | null;
  f?: string;
}

const dec = (s: string) =>
  s
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/_x([0-9A-Fa-f]{4})_/g, (_, h: string) => String.fromCharCode(parseInt(h, 16)));

const colIndex = (s: string) => [...s].reduce((n, ch) => n * 26 + ch.charCodeAt(0) - 64, 0) - 1;
const isError = (v: Value): v is { error: string } => typeof v === 'object' && v !== null && !Array.isArray(v);

export class Workbook {
  readonly sheets = new Map<string, Map<string, CellData>>();
  readonly names = new Map<string, string>();
  /** Language of the Excel that opens the workbook (separators of FIXED and of a number joined to a text). */
  locale: 'pt-BR' | 'en-US' = 'pt-BR';
  private readonly memo = new Map<string, Value>();
  private readonly ranges = new Map<string, Value[]>();

  /** Reads the workbook; `only` limits the sheets parsed (large workbooks). */
  static async read(blob: Blob, only?: string[]): Promise<Workbook> {
    const files = unzipSync(new Uint8Array(await blob.arrayBuffer()));
    const text = (n: string) => strFromU8(files[n]!);
    const wb = new Workbook();
    const workbook = text('xl/workbook.xml');
    const sheetNames = [...workbook.matchAll(/<sheet name="([^"]+)" sheetId="(\d+)"/g)].map((m) => dec(m[1]!));
    for (const m of workbook.matchAll(/<definedName name="([^"]+)"[^>]*>([^<]+)<\/definedName>/g)) wb.names.set(m[1]!, dec(m[2]!));
    sheetNames.forEach((name, i) => {
      if (only && !only.includes(name)) return;
      const xml = text(`xl/worksheets/sheet${i + 1}.xml`);
      const cells = new Map<string, CellData>();
      for (const c of xml.matchAll(/<c r="([A-Z]+\d+)"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)) {
        const attrs = c[2] ?? '';
        const body = c[3] ?? '';
        const f = /<f>([\s\S]*?)<\/f>/.exec(body)?.[1];
        const t = /t="(\w+)"/.exec(attrs)?.[1];
        let v: CellData['v'] = null;
        if (t === 'inlineStr') v = dec(/<t[^>]*>([\s\S]*?)<\/t>/.exec(body)?.[1] ?? '');
        else if (t === 'b') v = /<v>1<\/v>/.test(body);
        else {
          const raw = /<v>([^<]*)<\/v>/.exec(body)?.[1];
          if (raw !== undefined) v = Number(raw);
        }
        cells.set(c[1]!, { v, ...(f !== undefined && { f: dec(f) }) });
      }
      wb.sheets.set(name, cells);
    });
    return wb;
  }

  set(sheet: string, ref: string, v: CellData['v']): void {
    this.sheets.get(sheet)!.set(ref, { v });
    this.memo.clear();
    this.ranges.clear();
  }

  raw(sheet: string, ref: string): CellData | undefined {
    return this.sheets.get(sheet)?.get(ref);
  }

  /** Value of a cell, evaluating its formula. */
  value(sheet: string, ref: string): Value {
    const key = `${sheet}!${ref}`;
    const cached = this.memo.get(key);
    if (cached !== undefined) return cached;
    const cell = this.sheets.get(sheet)?.get(ref);
    let v: Value = null;
    if (cell?.f !== undefined) v = new Evaluator(this, sheet).evaluate(cell.f);
    else if (cell) v = cell.v;
    this.memo.set(key, v);
    return v;
  }

  range(sheet: string, from: string, to: string): Value[] {
    const key = `${sheet}!${from}:${to}`;
    const cached = this.ranges.get(key);
    if (cached) return cached;
    const a = /^([A-Z]+)(\d+)$/.exec(from)!;
    const b = /^([A-Z]+)(\d+)$/.exec(to)!;
    const out: Value[] = [];
    for (let r = Number(a[2]); r <= Number(b[2]); r++) {
      for (let c = colIndex(a[1]!); c <= colIndex(b[1]!); c++) {
        let name = '';
        let n = c + 1;
        while (n > 0) {
          const rem = (n - 1) % 26;
          name = String.fromCharCode(65 + rem) + name;
          n = Math.floor((n - 1) / 26);
        }
        out.push(this.value(sheet, `${name}${r}`));
      }
    }
    this.ranges.set(key, out);
    return out;
  }
}

type Token = { t: 'num' | 'str' | 'ref' | 'name' | 'op' | 'lp' | 'rp' | 'comma'; v: string };

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src[i]!;
    if (ch === ' ') {
      i++;
      continue;
    }
    if (ch === '"') {
      let s = '';
      i++;
      while (i < src.length) {
        if (src[i] === '"' && src[i + 1] === '"') {
          s += '"';
          i += 2;
        } else if (src[i] === '"') break;
        else s += src[i++];
      }
      i++;
      tokens.push({ t: 'str', v: s });
      continue;
    }
    const ref = /^(?:(?:'((?:[^']|'')+)'|([A-Za-z_][\w.]*))!)?\$?([A-Z]{1,3})\$?(\d+)(?::\$?([A-Z]{1,3})\$?(\d+))?/.exec(src.slice(i));
    if (ref && (ref[1] || ref[2] || !/^[A-Z]+\d*[(_]/.test(src.slice(i)))) {
      const sheet = ref[1]?.replace(/''/g, "'") ?? ref[2] ?? '';
      tokens.push({ t: 'ref', v: `${sheet}|${ref[3]}${ref[4]}|${ref[5] ? ref[5] + ref[6] : ''}` });
      i += ref[0].length;
      continue;
    }
    const num = /^\d+(\.\d+)?/.exec(src.slice(i));
    if (num) {
      tokens.push({ t: 'num', v: num[0] });
      i += num[0].length;
      continue;
    }
    const name = /^[A-Za-z_][\w.]*/.exec(src.slice(i));
    if (name) {
      tokens.push({ t: 'name', v: name[0] });
      i += name[0].length;
      continue;
    }
    const op = /^(<>|<=|>=|[-+*/&=<>])/.exec(src.slice(i));
    if (op) {
      tokens.push({ t: 'op', v: op[0] });
      i += op[0].length;
      continue;
    }
    if (ch === '(') tokens.push({ t: 'lp', v: ch });
    else if (ch === ')') tokens.push({ t: 'rp', v: ch });
    else if (ch === ',') tokens.push({ t: 'comma', v: ch });
    else throw new Error(`Token inesperado em "${src}": ${ch}`);
    i++;
  }
  return tokens;
}

const toNumber = (v: Value): number => {
  if (typeof v === 'number') return v;
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (v === null || v === '') return 0;
  if (typeof v === 'string' && v.trim() !== '' && !Number.isNaN(Number(v))) return Number(v);
  return Number.NaN;
};
const toText = (v: Value): string => (v === null ? '' : typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : String(v));
/** A number joined to a text ("&"): the decimal separator of the language of the user. */
const joinText = (v: Value, locale: Workbook['locale']): string => (typeof v === 'number' && locale === 'pt-BR' ? String(v).replace('.', ',') : toText(v));

/** FIXED(number, decimals): rounded half away from zero, with the group and decimal separators of the language. */
function fixed(n: number, decimals: number, locale: Workbook['locale']): string {
  const f = 10 ** decimals;
  const rounded = (Math.sign(n) * Math.round(Math.abs(n) * f + 1e-7)) / f;
  const [int, frac] = Math.abs(rounded).toFixed(Math.max(0, decimals)).split('.');
  const [group, point] = locale === 'pt-BR' ? ['.', ','] : [',', '.'];
  const grouped = int!.replace(/\B(?=(\d{3})+(?!\d))/g, group);
  return `${rounded < 0 ? '-' : ''}${grouped}${frac ? point + frac : ''}`;
}

/** Year, month and day of an Excel serial (1900 system; serial 60 is the 29/02/1900 that does not exist). */
function serialDate(serial: number): [number, number, number] {
  const s = Math.floor(serial);
  if (s === 60) return [1900, 2, 29];
  // Days since 1970-01-01 (civil-from-days, H. Hinnant).
  const z = s - (s < 60 ? 1 : 2) - 25567 + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp < 10 ? mp + 3 : mp - 9;
  return [yoe + era * 400 + (m <= 2 ? 1 : 0), m, d];
}
const flat = (v: Value): Value[] => (Array.isArray(v) ? v : [v]);

function compare(a: Value, b: Value, op: string): boolean {
  let c: number;
  if (typeof a === 'string' || typeof b === 'string') {
    const x = toText(a).toLowerCase();
    const y = toText(b).toLowerCase();
    c = x < y ? -1 : x > y ? 1 : 0;
  } else c = toNumber(a) - toNumber(b);
  switch (op) {
    case '=': return c === 0;
    case '<>': return c !== 0;
    case '<': return c < 0;
    case '>': return c > 0;
    case '<=': return c <= 0;
    default: return c >= 0;
  }
}

/** COUNTIFS/SUMIFS criterion, compiled once per call. */
function matcher(criterion: Value): (cell: Value) => boolean {
  if (typeof criterion === 'number') return (cell) => typeof cell === 'number' && cell === criterion;
  const s = toText(criterion);
  const m = /^(<>|<=|>=|<|>|=)?(.*)$/s.exec(s)!;
  const op = m[1] ?? '=';
  const target = m[2]!;
  if (target === '') return op === '<>' ? (cell) => cell !== null && cell !== '' : (cell) => cell === null || cell === '';
  const n = Number(target);
  if (!Number.isNaN(n) && target.trim() !== '') {
    // As Excel: an equality criterion that is a number also matches the texts that read as that number ("01" = 1).
    const numeric = (cell: Value) => (typeof cell === 'string' && cell.trim() !== '' && (op === '=' || op === '<>') ? Number(cell) : Number.NaN);
    return (cell) => (typeof cell === 'number' ? compare(cell, n, op) : !Number.isNaN(numeric(cell)) ? compare(numeric(cell), n, op) : op === '<>');
  }
  return (cell) => (cell === null ? op === '<>' : compare(toText(cell), target, op));
}

class Evaluator {
  private tokens: Token[] = [];
  private pos = 0;
  constructor(
    private readonly wb: Workbook,
    private readonly sheet: string,
  ) {}

  evaluate(formula: string): Value {
    this.tokens = tokenize(formula);
    this.pos = 0;
    try {
      return this.comparison();
    } catch (e) {
      return { error: (e as Error).message };
    }
  }

  private peek() {
    return this.tokens[this.pos];
  }
  private next() {
    return this.tokens[this.pos++]!;
  }

  private comparison(): Value {
    let left = this.concat();
    while (this.peek()?.t === 'op' && ['=', '<>', '<', '>', '<=', '>='].includes(this.peek()!.v)) {
      const op = this.next().v;
      const right = this.concat();
      left = this.binary(left, right, (a, b) => compare(a, b, op));
    }
    return left;
  }
  private concat(): Value {
    let left = this.additive();
    while (this.peek()?.v === '&') {
      this.next();
      const right = this.additive();
      left = this.binary(left, right, (a, b) => joinText(a, this.wb.locale) + joinText(b, this.wb.locale));
    }
    return left;
  }
  private additive(): Value {
    let left = this.term();
    while (this.peek()?.t === 'op' && (this.peek()!.v === '+' || this.peek()!.v === '-')) {
      const op = this.next().v;
      const right = this.term();
      left = this.binary(left, right, (a, b) => (op === '+' ? toNumber(a) + toNumber(b) : toNumber(a) - toNumber(b)));
    }
    return left;
  }
  private term(): Value {
    let left = this.unary();
    while (this.peek()?.t === 'op' && (this.peek()!.v === '*' || this.peek()!.v === '/')) {
      const op = this.next().v;
      const right = this.unary();
      left = this.binary(left, right, (a, b) => (op === '*' ? toNumber(a) * toNumber(b) : toNumber(a) / toNumber(b)));
    }
    return left;
  }
  private unary(): Value {
    if (this.peek()?.v === '-') {
      this.next();
      const v = this.unary();
      return Array.isArray(v) ? v.map((x) => -toNumber(x)) : -toNumber(v);
    }
    return this.primary();
  }
  private binary(a: Value, b: Value, fn: (x: Value, y: Value) => Value): Value {
    if (isError(a)) return a;
    if (isError(b)) return b;
    if (Array.isArray(a) || Array.isArray(b)) {
      const xs = flat(a);
      const ys = flat(b);
      const n = Math.max(xs.length, ys.length);
      return Array.from({ length: n }, (_, i) => fn(xs.length === 1 ? xs[0]! : xs[i]!, ys.length === 1 ? ys[0]! : ys[i]!));
    }
    return fn(a, b);
  }

  private reference(v: string): Value {
    const [sheet, from, to] = v.split('|');
    const s = sheet || this.sheet;
    return to ? this.wb.range(s, from!, to) : this.wb.value(s, from!);
  }

  private primary(): Value {
    const tok = this.next();
    if (tok.t === 'num') return Number(tok.v);
    if (tok.t === 'str') return tok.v;
    if (tok.t === 'ref') return this.reference(tok.v);
    if (tok.t === 'lp') {
      const v = this.comparison();
      this.next();
      return v;
    }
    if (tok.t === 'name') {
      if (this.peek()?.t === 'lp') {
        this.next();
        const args: (() => Value)[] = [];
        const slices: Token[][] = [];
        const starts: number[] = [];
        // Collect argument token ranges for lazy evaluation (IF, IFERROR).
        let depth = 0;
        let start = this.pos;
        if (this.peek()?.t !== 'rp') {
          while (this.pos < this.tokens.length) {
            const t = this.peek()!;
            if (t.t === 'lp') depth++;
            if (t.t === 'rp') {
              if (depth === 0) break;
              depth--;
            }
            if (t.t === 'comma' && depth === 0) {
              starts.push(start);
              slices.push(this.tokens.slice(start, this.pos));
              args.push(this.lazy(start, this.pos));
              this.next();
              start = this.pos;
              continue;
            }
            this.next();
          }
          slices.push(this.tokens.slice(start, this.pos));
          args.push(this.lazy(start, this.pos));
        }
        this.next(); // ")"
        return this.call(tok.v.toUpperCase(), args, slices);
      }
      if (tok.v === 'TRUE') return true;
      if (tok.v === 'FALSE') return false;
      const def = this.wb.names.get(tok.v);
      if (!def) return { error: `nome ${tok.v}` };
      return new Evaluator(this.wb, this.sheet).evaluate(def);
    }
    throw new Error(`token ${tok.v}`);
  }

  private lazy(from: number, to: number): () => Value {
    const slice = this.tokens.slice(from, to);
    return () => {
      const e = new Evaluator(this.wb, this.sheet);
      (e as unknown as { tokens: Token[] }).tokens = slice;
      return e.comparison();
    };
  }

  /** Rows of a range given as a reference or a defined name, without reading its cells (ROWS). */
  private rowsOf(tokens: Token[]): Value {
    if (tokens.length !== 1) return { error: 'ROWS de expressão' };
    const tok = tokens[0]!;
    if (tok.t === 'name') {
      const def = this.wb.names.get(tok.v);
      return def ? this.rowsOf(tokenize(def)) : { error: `nome ${tok.v}` };
    }
    if (tok.t !== 'ref') return { error: 'ROWS de expressão' };
    const [, from, to] = tok.v.split('|');
    const row = (ref: string) => Number(/\d+$/.exec(ref)![0]);
    return to ? row(to) - row(from!) + 1 : 1;
  }

  private call(name: string, args: (() => Value)[], slices: Token[][] = []): Value {
    const a = (i: number) => args[i]!();
    switch (name) {
      case 'ROWS': return this.rowsOf(slices[0] ?? []);
      case 'EXACT': return toText(a(0)) === toText(a(1));
      // Excel counts a formula that gives "" as not empty.
      case 'COUNTA': return args.reduce((n, _, i) => n + flat(a(i)).filter((x) => x !== null).length, 0);
      case 'WEEKDAY': {
        const serial = Math.floor(toNumber(a(0)));
        const type = args[1] ? toNumber(a(1)) : 1;
        if (type !== 2) return { error: 'WEEKDAY: só o tipo 2' };
        return ((((serial - 2) % 7) + 7) % 7) + 1;
      }
      case 'COUNTIF': {
        const range = flat(a(0));
        const count = (criterion: Value) => {
          const test = matcher(criterion);
          return range.filter((x) => test(x ?? null)).length;
        };
        // An array of criteria gives an array of counts (Excel, inside SUMPRODUCT).
        const criteria = a(1);
        return Array.isArray(criteria) ? criteria.map((c) => count(c ?? null)) : count(criteria);
      }
      case 'SUMIF': {
        const range = flat(a(0));
        const test = matcher(a(1));
        const values = args[2] ? flat(a(2)) : range;
        return range.reduce<number>((n, x, k) => (test(x ?? null) ? n + (toNumber(values[k] ?? 0) || 0) : n), 0);
      }
      case 'IF': {
        const c = a(0);
        return (typeof c === 'boolean' ? c : toNumber(c) !== 0) ? a(1) : args[2] ? a(2) : false;
      }
      case 'IFERROR': {
        const v = a(0);
        return isError(v) || (typeof v === 'number' && Number.isNaN(v)) ? a(1) : v;
      }
      case 'ISNUMBER': {
        const v = a(0);
        return typeof v === 'number' && Number.isFinite(v);
      }
      case 'AND': return args.every((_, i) => { const v = a(i); return typeof v === 'boolean' ? v : toNumber(v) !== 0; });
      case 'OR': return args.some((_, i) => { const v = a(i); return typeof v === 'boolean' ? v : toNumber(v) !== 0; });
      case 'NOT': { const v = a(0); return !(typeof v === 'boolean' ? v : toNumber(v) !== 0); }
      case 'LEN': return toText(a(0)).length;
      case 'TRIM': return toText(a(0)).trim().replace(/\s+/g, ' ');
      case 'ABS': return Math.abs(toNumber(a(0)));
      case 'ROUND': { const f = 10 ** toNumber(a(1)); return Math.round(toNumber(a(0)) * f + Number.EPSILON) / f; }
      case 'DATE': return 0; // not needed for values in the tests
      case 'DAY': return serialDate(toNumber(a(0)))[2];
      case 'MONTH': return serialDate(toNumber(a(0)))[1];
      case 'YEAR': return serialDate(toNumber(a(0)))[0];
      case 'FIXED': {
        const v = a(0);
        if (isError(v)) return v;
        const n = toNumber(v);
        return Number.isNaN(n) ? { error: '#VALUE!' } : fixed(n, args[1] ? toNumber(a(1)) : 2, this.wb.locale);
      }
      case 'LEFT': return toText(a(0)).slice(0, args[1] ? toNumber(a(1)) : 1);
      case 'RIGHT': { const t = joinText(a(0), this.wb.locale); const n = args[1] ? toNumber(a(1)) : 1; return n <= 0 ? '' : t.slice(-n); }
      case 'MID': return toText(a(0)).slice(toNumber(a(1)) - 1, toNumber(a(1)) - 1 + toNumber(a(2)));
      case 'LOWER': return toText(a(0)).toLowerCase();
      case 'SUM': return args.reduce((n, _, i) => n + flat(a(i)).reduce<number>((m, x) => m + (typeof x === 'number' ? x : 0), 0), 0);
      case 'MAX': return Math.max(...args.flatMap((_, i) => flat(a(i)).filter((x): x is number => typeof x === 'number')));
      case 'MIN': return Math.min(...args.flatMap((_, i) => flat(a(i)).filter((x): x is number => typeof x === 'number')));
      case 'SUMPRODUCT': {
        const arrays = args.map((_, i) => flat(a(i)).map(toNumber));
        return arrays[0]!.reduce((n, _, k) => n + arrays.reduce((p, arr) => p * (arr[k] ?? 0), 1), 0);
      }
      case 'INDEX': {
        const range = flat(a(0));
        const i = toNumber(a(1));
        if (!(i >= 1 && i <= range.length)) return { error: '#REF!' };
        return range[i - 1]!;
      }
      case 'MATCH': {
        const target = a(0);
        const range = flat(a(1));
        const i = range.findIndex((x) => x !== null && compare(x, target, '='));
        return i < 0 ? { error: '#N/A' } : i + 1;
      }
      case 'COUNTIFS':
      case 'SUMIFS': {
        const offset = name === 'SUMIFS' ? 1 : 0;
        const sumRange = offset ? flat(a(0)) : null;
        const pairs: [Value[], (cell: Value) => boolean][] = [];
        for (let i = offset; i < args.length; i += 2) pairs.push([flat(a(i)), matcher(a(i + 1))]);
        let total = 0;
        const n = pairs[0]![0].length;
        for (let k = 0; k < n; k++) {
          if (pairs.every(([range, test]) => test(range[k] ?? null))) total += sumRange ? toNumber(sumRange[k] ?? 0) || 0 : 1;
        }
        return total;
      }
      default:
        return { error: `função ${name}` };
    }
  }
}
